CREATE VIEW fct_sales_margin_regional AS
SELECT
  team_id,
  customer_id,
  period_month,
  region,
  CONCAT(LEFT(customer_phone, 3), '****', RIGHT(customer_phone, 4)) AS customer_phone_masked,
  sales,
  gross_margin
FROM fct_sales_margin
WHERE region = 'South_China';

